#!/usr/bin/env python3
"""Generate Vesktop/Vencord theme from DMS auto-generated colors.

Reads ~/.cache/DankMaterialShell/dms-colors.json and produces a CSS theme file.

Usage:
  python3 generate_vesktop_theme.py                                          # dark mode, flatpak path
  python3 generate_vesktop_theme.py --mode light                             # light mode
  python3 generate_vesktop_theme.py -o ~/.config/vesktop/themes/my.css       # custom output
  python3 generate_vesktop_theme.py --stdout                                 # print to stdout
"""

import argparse
import json
import os
import sys

DMS_COLORS_PATH = os.path.expanduser("~/.cache/DankMaterialShell/dms-colors.json")
FLATPAK_PATH = os.path.expanduser("~/.var/app/dev.vencord.Vesktop/config/vesktop/themes/dank-discord.css")
NATIVE_PATH = os.path.expanduser("~/.config/vesktop/themes/dank-discord.css")
VENOCRD_PATH = os.path.expanduser("~/.config/Vencord/themes/dank-discord.css")


def read_dms_colors(path):
    with open(path) as f:
        return json.load(f)


def extract_colors(dms_data, mode="dark"):
    colors = dms_data.get("colors", {}).get(mode, {})
    return {
        "surface": colors.get("surface", "#1a1c1e"),
        "surface_container_low": colors.get("surface_container_low", "#181a1d"),
        "surface_container": colors.get("surface_container", "#1e2023"),
        "surface_container_high": colors.get("surface_container_high", "#292b2f"),
        "surface_container_highest": colors.get("surface_container_highest", "#343740"),
        "on_surface": colors.get("on_surface", "#e3e8ef"),
        "on_surface_variant": colors.get("on_surface_variant", "#c4c7c5"),
        "primary": colors.get("primary", "#42a5f5"),
        "on_primary": colors.get("on_primary", "#ffffff"),
        "primary_container": colors.get("primary_container", "#0d47a1"),
        "on_primary_container": colors.get("on_primary_container", "#ffffff"),
        "secondary": colors.get("secondary", "#8ab4f8"),
        "secondary_container": colors.get("secondary_container", colors.get("surface_container_high", "#292b2f")),
        "on_secondary_container": colors.get("on_secondary_container", colors.get("on_surface", "#e3e8ef")),
        "tertiary": colors.get("tertiary", "#efb8c8"),
        "tertiary_container": colors.get("tertiary_container", colors.get("surface_container_high", "#292b2f")),
        "on_tertiary_container": colors.get("on_tertiary_container", colors.get("on_surface", "#e3e8ef")),
        "error": colors.get("error", "#F2B8B5"),
        "on_error": colors.get("on_error", "#601410"),
        "error_container": colors.get("error_container", "#8C1D18"),
        "on_error_container": colors.get("on_error_container", "#F9DEDC"),
        "outline": colors.get("outline", "#8e918f"),
        "outline_variant": colors.get("outline_variant", colors.get("surface_variant", "#44464f")),
    }


def generate_css(colors):
    template = _load_template()
    for key, val in colors.items():
        template = template.replace("{" + key + "}", val)
    return template


