def main():
    parser = argparse.ArgumentParser(description="Generate Vesktop theme from DMS colors")
    parser.add_argument("-m", "--mode", choices=["dark", "light"], default="dark",
                        help="Color mode (default: dark)")
    parser.add_argument("-o", "--output",
                        help="Output path (default: auto-detect flatpak or native)")
    parser.add_argument("--stdout", action="store_true", help="Print CSS to stdout")
    args = parser.parse_args()

    if not os.path.exists(DMS_COLORS_PATH):
        print(f"Error: {DMS_COLORS_PATH} not found.", file=sys.stderr)
        sys.exit(1)

    dms_data = read_dms_colors(DMS_COLORS_PATH)
    colors = extract_colors(dms_data, args.mode)
    css = generate_css(colors)

    if args.stdout:
        print(css)
        return

    output = args.output
    if not output:
        flatpak_dir = os.path.dirname(FLATPAK_PATH)
        if os.path.exists(flatpak_dir):
            output = FLATPAK_PATH
        else:
            output = NATIVE_PATH

    os.makedirs(os.path.dirname(os.path.abspath(output)), exist_ok=True)
    with open(output, "w") as f:
        f.write(css)
    print(f"Written: {output}")
    print(f"Enable it in Vesktop: Settings → Themes → open Themes folder → place file there")
    print(f"  or for Vencord: cp '{output}' '{VENOCRD_PATH}'")


if __name__ == "__main__":
    main()
